# Fixes the real bug: newsletter_subscribers has no created_at column,
# the real column is subscribed_at. Updates both the API query and
# the page's type/rendering to match.

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\api\admin\subscribers\route.ts"), $bytes)
Write-Host "UPDATED: src\app\api\admin\subscribers\route.ts" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\admin\subscribers\page.tsx"), $bytes)
Write-Host "UPDATED: src\app\admin\subscribers\page.tsx" -ForegroundColor Green

Write-Host "`nBoth files written." -ForegroundColor Cyan
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan